  (uuid_generate_v4(), 'black-embroidered-snip-toe-boots', 'Black Embroidered Snip Toe Boots', 'Circle G Elegant, simple, and beautiful. This is the ideal black boot with its simple embroidery pattern. Throughout the 13-inch shaft is a black embroidery pattern, this beautiful boot deserves to be in every wardrobe. You can wear this style all day without worrying about getting tired. It features sturdy pull-on straps, an elegant snip, smooth inside leather lining, cushioned leather insole, a leather outer sole, and a 2-inch heel.', 179.00, 'footwear', ARRAY['https://cdn.shopify.com/s/files/1/0053/8447/0592/files/rn-image_picker_lib_temp_7259abd6-4099-4646-94ee-de9f50181430.jpg?v=1781212597','https://cdn.shopify.com/s/files/1/0053/8447/0592/files/rn-image_picker_lib_temp_d4120948-c7fd-4746-8b43-866911d01e56.jpg?v=1781212596'], ARRAY['7','8','9','10'], 'Shoe size', 'My Pretty in Pink', ARRAY['boots'], TRUE, NOW(), NOW()),
  (uuid_generate_v4(), 'corral-black-alligator-inlay-embroidered-men-boots', 'Corral Black Alligator Inlay & Embroidered Men''s Boots', 'Gallant, distinctive, and bold. A classic style for the city or country life, a boot for a true cowboy wherever he may be. The embroidery pattern along the 12-inch shaft shows the classic Western style. These eye-catching alligator boots will be the center of attention wherever you take them. You can wear this style all day without worrying about getting tired. It features; sturdy pull-on straps and a comfortable, wide square toe. The smooth inside leather lining, cushioned leather insole, leather outer sole, and 1.5-inch heel.', 619.00, 'footwear', ARRAY['https://cdn.shopify.com/s/files/1/0053/8447/0592/files/rn-image_picker_lib_temp_22c942ac-3106-4bda-9a66-53fc85e0112b.jpg?v=1781214414','https://cdn.shopify.com/s/files/1/0053/8447/0592/files/rn-image_picker_lib_temp_cf63b171-d54c-4bc4-841c-c28486adc551.jpg?v=1781214414'], ARRAY['8','9','10','11'], 'Shoe size', 'My Pretty in Pink', ARRAY['boots'], TRUE, NOW(), NOW()),
  (uuid_generate_v4(), 'corral-honey-alligator-inlay-embroidered-mens-boot', 'Corral Honey Alligator Inlay & Embroidered Men''s Boot', 'The embroidery pattern along the 12-inch shaft shows the classic Western style. These eye-catching alligator boots will be the center of attention wherever you take them. You can wear this style all day without worrying about getting tired. It features; sturdy pull-on straps and a comfortable, wide square toe. The smooth inside leather lining, cushioned leather insole, leather outer sole, and 1.5-inch heel.', 619.00, 'footwear', ARRAY['https://cdn.shopify.com/s/files/1/0053/8447/0592/files/rn-image_picker_lib_temp_1680ab18-0b4a-46c4-bb87-9722b7725842.jpg?v=1781215979','https://cdn.shopify.com/s/files/1/0053/8447/0592/files/rn-image_picker_lib_temp_b58bbcd5-60f7-4304-b546-13c6edb9b964.jpg?v=1781215979','https://cdn.shopify.com/s/files/1/0053/8447/0592/files/rn-image_picker_lib_temp_9004c1cf-c396-42ca-baca-fa5591a3cd2d.jpg?v=1781215979'], ARRAY['8','9','10','11'], 'Shoe size', 'My Pretty in Pink', ARRAY['boots'], TRUE, NOW(), NOW())
